import{_ as i,a0 as r,w as o,s as d,I as n,x as e,a1 as t,A as p,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"服務器推送事件：一種從服務器流式推送事件的簡易方法 | LCTT x X-CMD","titleTemplate":false,"description":"服務器推送事件：一種從服務器流式推送事件的簡易方法 | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"服務器推送事件：一種從服務器流式推送事件的簡易方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"服務器推送事件：一種從服務器流式推送事件的簡易方法 | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20210112 Server-sent events- a simple way to stream events from a server","title":"服務器推送事件：一種從服務器流式推送事件的簡易方法","tag":"202305","desc":""},"relativePath":"202305/20210112 Server-sent events- a simple way to stream events from a server.md","filePath":"[post].md"}'),u={name:"202305/20210112 Server-sent events- a simple way to stream events from a server.md"};function g(v,s,f,h,k,b){const a=r("Link");return o(),d("div",null,[s[36]||(s[36]=n("h1",{id:"服務器推送事件-一種從服務器流式推送事件的簡易方法",tabindex:"-1"},[e("服務器推送事件：一種從服務器流式推送事件的簡易方法 "),n("a",{class:"header-anchor",href:"#服務器推送事件-一種從服務器流式推送事件的簡易方法","aria-label":"Permalink to “服務器推送事件：一種從服務器流式推送事件的簡易方法”"},"​")],-1)),s[37]||(s[37]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202305/10/085812xdwdd0lhh0il5e5k.jpg",alt:""})],-1)),n("p",null,[s[2]||(s[2]=e("哈嘍！昨天我見識到了一種我以前從沒見過的從服務器推送事件的炫酷方法：",-1)),n("ruby",null,[t(a,{href:"https://html.spec.whatwg.org/multipage/server-sent-events.html"},{default:p(()=>[...s[0]||(s[0]=[e("服務器推送事件",-1)])]),_:1}),s[1]||(s[1]=n("rt",null,"server-sent events",-1))]),s[3]||(s[3]=e("！如果你只需要讓服務器發送事件，相較於 Websockets，它們或許是一個更簡便的選擇。",-1))]),s[38]||(s[38]=l(`<p>我會聊一聊它們的用途、運作原理，以及我昨日在試着運行它們的過程中遇到的幾個錯誤。</p><h3 id="問題-從服務器流式推送更新" tabindex="-1">問題：從服務器流式推送更新 <a class="header-anchor" href="#問題-從服務器流式推送更新" aria-label="Permalink to “問題：從服務器流式推送更新”">​</a></h3><p>現在，我有一個啓動虛擬機的 Web 服務，客户端輪詢服務器，直到虛擬機啓動。但我並不想使用輪詢方式。</p><p>相反，我想讓服務器流式推送更新。我跟 Kamal 説我要用 Websockets 來實現它，而他建議使用服務器推送事件不失為一個更簡便的選擇！</p><p>我登時就愣住了——那什麼玩意？？？聽起來像是些我從來沒見過的稀罕玩意兒。於是乎我就查了查。</p><h3 id="服務器推送事件就是個-http-請求協議" tabindex="-1">服務器推送事件就是個 HTTP 請求協議 <a class="header-anchor" href="#服務器推送事件就是個-http-請求協議" aria-label="Permalink to “服務器推送事件就是個 HTTP 請求協議”">​</a></h3><p>下文便是服務器推送事件的運作流程。我-很-高-興-地瞭解到它們就是個 HTTP 請求協議。</p><p>1.客户端提出一個 GET 請求（舉個例子）<code>https://yoursite.com/events</code> 2.客户端設置 <code>Connection: keep-alive</code>，這樣我們就能有一個長連接 3.服務器設置設置一個 <code>Content-Type: text/event-stream</code> 響應頭 4.服務器開始推送事件，就比如下文這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>event: status</span></span>
<span class="line"><span>data: one</span></span></code></pre></div><p>舉個例子，這裏是當我藉助 <code>curl</code> 發送請求時，一些服務器推送事件的樣子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -N &#39;http://localhost:3000/sessions/15/stream&#39;</span></span>
<span class="line"><span>event: panda</span></span>
<span class="line"><span>data: one</span></span>
<span class="line"><span></span></span>
<span class="line"><span>event: panda</span></span>
<span class="line"><span>data: two</span></span>
<span class="line"><span></span></span>
<span class="line"><span>event: panda</span></span>
<span class="line"><span>data: three</span></span>
<span class="line"><span></span></span>
<span class="line"><span>event: elephant</span></span>
<span class="line"><span>data: four</span></span></code></pre></div><p>服務器可以根據時間推移緩慢推送事件，並且客户端也能夠在它們到來時讀取它們。你也可以將 JSON 或任何你想要的東西放在事件當中，就比如 <code>data: {&#39;name&#39;: &#39;ahmed&#39;}</code>。</p><p>線路協議真的很簡單（只需要設置 <code>event:</code> 和 <code>data:</code>，或者如果你願意，可設置為 <code>id:</code> 和 <code>retry:</code>），所以你並不需要任何花裏胡哨的服務器庫來實現服務器推送事件。</p><h3 id="javascript-的代碼也超級簡單-僅使用-eventsource" tabindex="-1">JavaScript 的代碼也超級簡單（僅使用 EventSource） <a class="header-anchor" href="#javascript-的代碼也超級簡單-僅使用-eventsource" aria-label="Permalink to “JavaScript 的代碼也超級簡單（僅使用 EventSource）”">​</a></h3>`,14)),n("p",null,[s[5]||(s[5]=e("以下是用於流式服務器推送事件的瀏覽器 JavaScript 的代碼。（我從 ",-1)),t(a,{href:"https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events/Using_server-sent_events"},{default:p(()=>[...s[4]||(s[4]=[e("服務器推送事件的 MND 頁面",-1)])]),_:1}),s[6]||(s[6]=e(" 得到的這個範例）",-1))]),s[39]||(s[39]=l(`<p>你可以訂閲所有事件，也可以為不同類型的事件使用不同的處理程序。這裏我有一個只接受類型為 <code>panda</code> 的事件的處理程序（就像我們的服務器在上一節中推送的那樣）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>const evtSource = new EventSource(&quot;/sessions/15/stream&quot;, { withCredentials: true })</span></span>
<span class="line"><span>evtSource.addEventListener(&quot;panda&quot;, function(event) {</span></span>
<span class="line"><span>  console.log(&quot;status&quot;, event)</span></span>
<span class="line"><span>});</span></span></code></pre></div><h3 id="客户端在中途不能推送更新" tabindex="-1">客户端在中途不能推送更新 <a class="header-anchor" href="#客户端在中途不能推送更新" aria-label="Permalink to “客户端在中途不能推送更新”">​</a></h3><p>不同於 Websockets，服務器推送事件不允許大量的來回事件通訊。（這體現在它的字眼中 —— <strong>服務器</strong> 推送所有事件）。初始的時候客户端發出一個請求，然後服務器發出一連串響應。</p><h3 id="如果-http-連接結束-它會自動重連" tabindex="-1">如果 HTTP 連接結束，它會自動重連 <a class="header-anchor" href="#如果-http-連接結束-它會自動重連" aria-label="Permalink to “如果 HTTP 連接結束，它會自動重連”">​</a></h3><p>使用 <code>EventSource</code> 發出的 HTTP 請求和常規 HTTP 請求有一個很大的區別，MDN 文檔中對此有所説明：</p><blockquote><p>默認情況下，如果客户端和服務器之間的連接斷開，則連接會重啓。請使用 <code>.close()</code> 方法來終止連接。</p></blockquote><p>很奇怪，一開始我真的被它嚇到了：我打開了一個連接，然後在服務器端將其關閉，然後兩秒過後客户端向我的傳送終端發送了另一條請求！</p><p>我覺得這裏可能是因為連接在完成之前意外斷開了，所以客户端自動重新打開了它以防止類似情況再發生。</p><p>所以如果你不想讓客户端繼續重試，你就得通過調用 <code>.close()</code> 直截了當地關閉連接。</p><h3 id="這裏還有些其它特性" tabindex="-1">這裏還有些其它特性 <a class="header-anchor" href="#這裏還有些其它特性" aria-label="Permalink to “這裏還有些其它特性”">​</a></h3><p>你還能在服務器推送事件中設置 <code>id:</code> 和 <code>retry:</code> 字段。似乎，如果你在服務器推送事件上設置，那麼當重新連接時，客户端將發送一個 <code>Last-Event-ID</code> 響應頭，帶有它收到的最後一個 ID。酷!</p>`,12)),n("p",null,[s[8]||(s[8]=e("我發現 ",-1)),t(a,{href:"https://html.spec.whatwg.org/multipage/server-sent-events.html#event-stream-interpretation"},{default:p(()=>[...s[7]||(s[7]=[e("W3C 的服務器推送事件頁面",-1)])]),_:1}),s[9]||(s[9]=e(" 令人驚訝地容易理解。",-1))]),s[40]||(s[40]=l(`<h3 id="在設置服務器推送事件的時候我遇到了兩個錯誤" tabindex="-1">在設置服務器推送事件的時候我遇到了兩個錯誤 <a class="header-anchor" href="#在設置服務器推送事件的時候我遇到了兩個錯誤" aria-label="Permalink to “在設置服務器推送事件的時候我遇到了兩個錯誤”">​</a></h3><p>我在 Rails 中使用服務器推送事件時遇到了幾個問題，我認為這些問題挺有趣的。其中一個緣於 Nginx，另一個是由 Rails 引起的。</p><p><strong>問題一：我不能在事件推送的過程中暫停</strong></p><p>這個奇怪的錯誤是在我做以下操作時出現的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def handler</span></span>
<span class="line"><span>    # SSE is Rails&#39; built in server-sent events thing</span></span>
<span class="line"><span>    sse = SSE.new(response.stream, event: &quot;status&quot;)</span></span>
<span class="line"><span>    sse.write(&#39;event&#39;)</span></span>
<span class="line"><span>    sleep 1</span></span>
<span class="line"><span>    sse.write(&#39;another event&#39;)</span></span>
<span class="line"><span>end</span></span></code></pre></div>`,5)),n("p",null,[s[11]||(s[11]=e("它會寫入第一個事件，但不能寫入第二個事件。我對此-非-常-困-惑，然後放開腦洞，試着理解 Ruby 中的 ",-1)),s[12]||(s[12]=n("code",null,"sleep",-1)),s[13]||(s[13]=e(" 是如何運作的。但是 Cass 將我引領到一個與我有着相同困惑的 ",-1)),t(a,{href:"https://stackoverflow.com/questions/25660399/sse-eventsource-closes-after-first-chunk-of-data-rails-4-puma-nginx"},{default:p(()=>[...s[10]||(s[10]=[e("Stack Overflow 問答帖",-1)])]),_:1}),s[14]||(s[14]=e("，而這裏包含了讓我為之震驚的回答！",-1))]),s[41]||(s[41]=n("p",null,"事實證明，問題出在我的 Rails 服務器位於 Nginx 之後，似乎 Nginx 默認使用 HTTP/1.0 向上遊服務器發起請求（為啥？都 2021 年了，還這麼幹？我相信這其中一定有合乎情理的解釋，也許是為了向下兼容之類的）。",-1)),s[42]||(s[42]=n("p",null,[e("所以客户端（Nginx）會在服務器推送第一個事件之後直接關閉連接。我覺得如果在我推送第二個事件的過程中 "),n("em",null,"沒有"),e(" 暫停，它繼續正常工作，基本上就是服務器在連接關閉之前和客户端在爭速度，爭着推送第二部分響應，如果我這邊推送速度足夠快，那麼服務器就會贏得比賽。")],-1)),s[43]||(s[43]=n("p",null,"我不確定為什麼使用 HTTP/1.0 會使客户端的連接關閉（可能是因為服務器在每個事件結尾寫入了兩個換行符？），但因為服務器推送事件是一個比較新的玩意兒，HTTP/1.0 （這種老舊協議）不支持它一點都會不意外。",-1)),s[44]||(s[44]=n("p",null,[e("設置 "),n("code",null,"proxy_http_version 1.1"),e(" 從而解決那個麻煩。好欸！")],-1)),s[45]||(s[45]=n("p",null,[n("strong",null,"問題二：事件被緩衝")],-1)),n("p",null,[s[16]||(s[16]=e("這個事情解決完，第二個麻煩接踵而至。不過這個問題實際上非常好解決，因為 Cass 已經建議將 ",-1)),t(a,{href:"https://stackoverflow.com/questions/63432012/server-sent-events-in-rails-not-delivered-asynchronously/65127528#65127528"},{default:p(()=>[...s[15]||(s[15]=[e("stackoverflow 裏另一篇帖的回答",-1)])]),_:1}),s[17]||(s[17]=e(" 作為前一個問題的解決方案，雖然它並沒有是導致問題一齣現的源頭，但它-確-實-解-釋-了問題二。",-1))]),s[46]||(s[46]=l(`<p>問題在這個示例代碼中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def handler</span></span>
<span class="line"><span>    response.headers[&#39;Content-Type&#39;] = &#39;text/event-stream&#39;</span></span>
<span class="line"><span>    # Turn off buffering in nginx</span></span>
<span class="line"><span>    response.headers[&#39;X-Accel-Buffering&#39;] = &#39;no&#39;</span></span>
<span class="line"><span>    sse = SSE.new(response.stream, event: &quot;status&quot;)</span></span>
<span class="line"><span>    10.times do</span></span>
<span class="line"><span>        sse.write(&#39;event&#39;)</span></span>
<span class="line"><span>        sleep 1</span></span>
<span class="line"><span>    end</span></span>
<span class="line"><span>end</span></span></code></pre></div><p>我本來期望它每秒返回 1 個事件，持續 10 秒，但實際上它等了 10 秒才把 10 個事件一起返回。這不是我們想要的流式傳輸方式！</p><p>原來這是因為 Rack ETag 中間件想要計算 ETag（響應的哈希值），為此它需要整個響應為它服務。因此，我需要禁用 ETag 生成。</p>`,4)),n("p",null,[s[19]||(s[19]=e("Stack Overflow 的回答建議完全禁用 Rack ETag 中間件，但我不想這樣做，於是我去看了 ",-1)),t(a,{href:"https://github.com/rack/rack/issues/1619"},{default:p(()=>[...s[18]||(s[18]=[e("鏈接至 GitHub 上的議題",-1)])]),_:1}),s[20]||(s[20]=e("。",-1))]),s[47]||(s[47]=l('<p>那個 GitHub 議題建議我可以針對僅流式傳輸終端應用一個解決方法，即 <code>Last-Modified</code> 響應頭，顯然，這麼做可以繞過 ETag 中間件。</p><p>所以我設置為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>headers[&#39;Last-Modified&#39;] = Time.now.httpdate</span></span></code></pre></div><p>然後它起作用了！！！</p><p>我還通過設置響應頭 <code>X-Accel-Buffering: no</code> 關閉了位於 Nginx 中的緩衝區。我並沒有百分百確定我要那樣做，但這麼做似乎更安全。</p><h3 id="stack-overflow-很棒" tabindex="-1">Stack Overflow 很棒 <a class="header-anchor" href="#stack-overflow-很棒" aria-label="Permalink to “Stack Overflow 很棒”">​</a></h3><p>起初，我全身心致力於從頭開始調試這兩個錯誤。Cass 為我指向了那兩個 Stack Overflow 帖子，一開始我對那些帖下提出的解決方案持懷疑態度（我想：“我沒有使用 HTTP/1.0 啊！ETag 響應頭什麼玩意，跟這一切有關係嗎？？”）。</p><p>但結果證明，我確實無意中使用 <em>了</em> HTTP/1.0，並且 Rack ETag 中間件確實給我帶來了問題。</p><p>因此，也許這個故事告訴我，有時候計算機就是會以奇怪的方式相互作用，其它人在過去也遇到過計算機以完全相同的奇怪方式相互作用的問題，而 Stack Overflow 有時會提供關於為什麼會發生這些情況的答案 : )</p><p>我認為重要的是不要隨意從 Stack Overflow 中嘗試各種解決方案（當然，在這種情況下不會有人建議這樣做！）。對於這兩個問題，我確實需要去仔細思考，瞭解發生了什麼，還有為什麼更改這些設置會起作用。</p><h3 id="就是這樣" tabindex="-1">就是這樣！ <a class="header-anchor" href="#就是這樣" aria-label="Permalink to “就是這樣！”">​</a></h3><p>今天我要繼續着手實現服務器推送事件，因為昨天一整天我都沉浸在上述這些錯誤裏。好在我學到了一個以前從未聽説過的易學易用的網絡技術，心裏還是很高興的。</p><p><em>（題圖：MJ/4c08a193-086e-4efe-a662-00401c928c41）</em></p><hr>',14)),n("p",null,[s[22]||(s[22]=e("via: ",-1)),t(a,{href:"https://jvns.ca/blog/2021/01/12/day-36--server-sent-events-are-cool--and-a-fun-bug/"},{default:p(()=>[...s[21]||(s[21]=[e("https://jvns.ca/blog/2021/01/12/day-36--server-sent-events-are-cool--and-a-fun-bug/",-1)])]),_:1})]),n("p",null,[s[27]||(s[27]=e("作者：",-1)),t(a,{href:"https://jvns.ca/"},{default:p(()=>[...s[23]||(s[23]=[e("Julia Evans",-1)])]),_:1}),s[28]||(s[28]=e(" 選題：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[24]||(s[24]=[e("lujun9972",-1)])]),_:1}),s[29]||(s[29]=e(" 譯者：",-1)),t(a,{href:"https://github.com/Drwhooooo"},{default:p(()=>[...s[25]||(s[25]=[e("Drwhooooo",-1)])]),_:1}),s[30]||(s[30]=e(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:p(()=>[...s[26]||(s[26]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[33]||(s[33]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[31]||(s[31]=[e("LCTT",-1)])]),_:1}),s[34]||(s[34]=e(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:p(()=>[...s[32]||(s[32]=[e("Linux中國",-1)])]),_:1}),s[35]||(s[35]=e(" 榮譽推出",-1))])])}const c=i(u,[["render",g]]);export{S as __pageData,c as default};
